window.ARCANA_TR = function(str, lang){
  lang = lang || (document.documentElement.lang || 'en');
  const T = window.ARCANA_TERMS[lang];
  if(!str || !T || !T.exact) return str;
  if(T.exact[str] != null) return T.exact[str];
  let out = String(str);
  const toks = Object.keys(T.tokens).sort((a,b)=>b.length-a.length);
  for(const en of toks) if(out.indexOf(en)>-1) out = out.split(en).join(T.tokens[en]);
  return out;
};
/* translate a UI label */
window.ARCANA_T = function(key, lang){
  lang = lang || (document.documentElement.lang || 'en');
  const T = window.ARCANA_TERMS[lang];
  if(!T || !T.ui || T.ui[key]==null) return key;
  return T.ui[key];
};
/* localise a USD amount to the active currency */
window.ARCANA_money = function(usd, lang){
  lang = lang || (document.documentElement.lang || 'en');
  const f = window.ARCANA_FX[lang] || window.ARCANA_FX.en;
  const v = (usd||0) * f.rate;
  return f.sym + v.toLocaleString(f.loc, {minimumFractionDigits:f.dec, maximumFractionDigits:f.dec});
};
/* tiered QC/insurance rates — below US$1000 subtotal vs. US$1000 and above */
window.ARCANA_addonRates = function(subtotal){
  const under = subtotal < 1000;
  return { qc: under ? 0.02 : 0.01, ins: under ? 0.01 : 0.005 };
};
